/** `define()` on models generated by an older ORM names the cure. */
import assert from "node:assert/strict";
import { test } from "node:test";
import { define, Registry, SchemaError, type SchemaIR } from "../src/index.js";

test("define rejects an old schema contract and names the cure", () => {
  const ir = { models: [], behavior: { schema_contract: 2 } } as unknown as SchemaIR;
  assert.throws(() => define(ir, { registry: new Registry() }), (e: unknown) => e instanceof SchemaError && /schema contract 2 is older than this engine .*regenerate the models and rebuild the native artifact/.test(e.message));
});

test("define rejects old proxy models and names the cure", () => {
  const ir = { models: [], behavior: { proxy_models: [{ model: "A", parent: "U", defaults: {} }] } } as unknown as SchemaIR;
  assert.throws(() => define(ir, { registry: new Registry() }), (e: unknown) => e instanceof SchemaError && /unknown field `proxy_models`.*regenerate the models and rebuild the native artifact/.test(e.message));
});
